SELECT s1.`c0` AS `d`, s1.`c1` AS `next_day`, s1.`c2` AS `later` FROM (SELECT s2.`c7` AS `c0`, s2.`c8` AS `c1`, s2.`c9` AS `c2` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4`, s3.`c5` AS `c5`, s3.`c6` AS `c6`, s3.`c0` AS `c7`, (CASE WHEN (CAST(unix_date(s3.`c0`) AS BIGINT) NOT BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT) OR CAST(unix_date(date_add((CASE WHEN CAST(unix_date(s3.`c0`) AS BIGINT) BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT) THEN s3.`c0` END), CAST(CAST(1 AS BIGINT) AS INT))) AS BIGINT) NOT BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT)) THEN (CASE WHEN s3.`c0` IS NULL THEN CAST(NULL AS DATE) ELSE CAST(raise_error(concat('sverify: date + days outside the dates DataFusion computes: ', CAST(s3.`c0` AS STRING))) AS DATE) END) ELSE date_add((CASE WHEN CAST(unix_date(s3.`c0`) AS BIGINT) BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT) THEN s3.`c0` END), CAST(CAST(1 AS BIGINT) AS INT)) END) AS `c8`, (s3.`c0` < (CASE WHEN (CAST(unix_date(s3.`c0`) AS BIGINT) NOT BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT) OR CAST(unix_date(date_add((CASE WHEN CAST(unix_date(s3.`c0`) AS BIGINT) BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT) THEN s3.`c0` END), CAST(CAST(7 AS BIGINT) AS INT))) AS BIGINT) NOT BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT)) THEN (CASE WHEN s3.`c0` IS NULL THEN CAST(NULL AS DATE) ELSE CAST(raise_error(concat('sverify: date + days outside the dates DataFusion computes: ', CAST(s3.`c0` AS STRING))) AS DATE) END) ELSE date_add((CASE WHEN CAST(unix_date(s3.`c0`) AS BIGINT) BETWEEN CAST(-96465292 AS BIGINT) AND CAST(95026236 AS BIGINT) THEN s3.`c0` END), CAST(CAST(7 AS BIGINT) AS INT)) END)) AS `c9` FROM (SELECT `d` AS `c0`, `d2` AS `c1`, `ts` AS `c2`, `x` AS `c3`, `s` AS `c4`, `ok` AS `c5`, (`v` + CAST('0' AS DOUBLE)) AS `c6` FROM `events`) AS s3) AS s2) AS s1
